var activeTicket=null;
function draftSnapshot(){if(!activeTicket||activeTicket.level!=="B")return;var panel=$("#engineMount"),grid=panel&&panel.querySelector(".bf-form-grid");var fields=grid?[].slice.call(grid.querySelectorAll("input,select,textarea")).filter(function(x){return x.type!=="file"}).map(function(x){return {id:x.id||"",name:x.name||"",type:x.type||"",value:x.value,checked:!!x.checked}}):[];var resultBox=$("engineResult");var payload={fields:fields,result:resultBox?resultBox.innerHTML:"",resultClass:resultBox?resultBox.className:"bf-result info"};try{localStorage.setItem("yi-ticket-form-"+activeTicket.id,JSON.stringify(payload))}catch(e){}}
function restoreDraftFields(t){activeTicket=t;if(t.level!=="B")return null;try{var payload=JSON.parse(localStorage.getItem("yi-ticket-form-"+t.id)||"null");if(!payload||!Array.isArray(payload.fields))return payload;var grid=$("#engineMount")&&$("#engineMount").querySelector(".bf-form-grid");if(!grid)return payload;var fields=[].slice.call(grid.querySelectorAll("input,select,textarea")).filter(function(x){return x.type!=="file"});fields.forEach(function(x,i){var saved=payload.fields[i];if(!saved)return;if(x.type==="checkbox"||x.type==="radio")x.checked=!!saved.checked;else x.value=saved.value==null?"":saved.value});return payload}catch(e){return null}}
