var positive=function(id,label,zero){var v=num(id);if(!Number.isFinite(v)||(zero?v<0:v<=0)){show(esc(label)+" qiymatini "+(zero?"manfiy bo‘lmagan":"noldan katta")+" son kiriting.","error");return null}return v};
